import re
from datetime import datetime, timedelta, timezone
from decimal import Decimal
from mcp.server.fastmcp import FastMCP
from custody_client import CustodyClient

mcp = FastMCP("wallet-ops")
custody = CustodyClient.from_env()

_ADDRESS_RE = re.compile(r"^0x[a-fA-F0-9]{40}$")
_MAX_SPEND_USD = Decimal("10000")
_MAX_GAS_ETH = Decimal("0.05")


@mcp.tool()
def grant_funded_session_key(
    wallet_id: str,
    session_address: str,
    spend_limit_usd: float,
    ttl_hours: int,
    gas_amount_eth: float,
) -> dict:
    if not wallet_id or not wallet_id.strip():
        return {"ok": False, "error": "wallet_id is required"}
    if not _ADDRESS_RE.match(session_address or ""):
        return {"ok": False, "error": "session_address must be a 0x-prefixed 20-byte hex address"}
    limit = Decimal(str(spend_limit_usd))
    if limit <= 0 or limit > _MAX_SPEND_USD:
        return {"ok": False, "error": f"spend_limit_usd must be between 0 and {_MAX_SPEND_USD}"}
    if ttl_hours < 1 or ttl_hours > 168:
        return {"ok": False, "error": "ttl_hours must be between 1 and 168"}
    gas = Decimal(str(gas_amount_eth))
    if gas <= 0 or gas > _MAX_GAS_ETH:
        return {"ok": False, "error": f"gas_amount_eth must be between 0 and {_MAX_GAS_ETH}"}

    wallet = custody.wallets.get(wallet_id)
    if wallet is None:
        return {"ok": False, "error": f"wallet {wallet_id} not found"}
    if wallet.get("frozen"):
        return {"ok": False, "error": "wallet is frozen"}
    if session_address.lower() == wallet["address"].lower():
        return {"ok": False, "error": "session_address cannot be the wallet's own address"}
    if Decimal(wallet["balances"].get("ETH", "0")) < gas:
        return {"ok": False, "error": "insufficient ETH balance for gas funding"}

    expires_at = datetime.now(timezone.utc) + timedelta(hours=ttl_hours)
    grant = custody.session_keys.grant(
        wallet_id=wallet_id,
        signer_address=session_address,
        spend_limit_usd=str(limit),
        expires_at=expires_at.isoformat(),
    )
    transfer = custody.transfers.send(
        wallet_id=wallet_id,
        asset="ETH",
        amount=str(gas),
        to_address=session_address,
        memo=f"gas for session key {grant['id']}",
    )
    return {
        "ok": True,
        "session_key_id": grant["id"],
        "expires_at": expires_at.isoformat(),
        "spend_limit_usd": str(limit),
        "gas_tx_hash": transfer["tx_hash"],
    }

import sqlite3
from contextlib import closing
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("wallet-ops")
DB_PATH = "/var/lib/wallet/wallet.db"


def _connect() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


@mcp.tool()
def remove_multisig_signer(wallet_id: str, member_id: str) -> dict:
    with closing(_connect()) as conn:
        with conn:
            wallet = conn.execute(
                "SELECT id, threshold FROM multisig_wallets WHERE id = ?",
                (wallet_id,),
            ).fetchone()
            if wallet is None:
                return {"ok": False, "error": f"wallet {wallet_id} not found"}

            signer = conn.execute(
                "SELECT member_id FROM wallet_signers WHERE wallet_id = ? AND member_id = ?",
                (wallet_id, member_id),
            ).fetchone()
            if signer is None:
                return {"ok": False, "error": f"{member_id} is not a signer on {wallet_id}"}

            count = conn.execute(
                "SELECT COUNT(*) FROM wallet_signers WHERE wallet_id = ?",
                (wallet_id,),
            ).fetchone()[0]
            if count - 1 < wallet["threshold"]:
                return {
                    "ok": False,
                    "error": f"removing would leave {count - 1} signers below threshold {wallet['threshold']}",
                }

            conn.execute(
                "DELETE FROM wallet_signers WHERE wallet_id = ? AND member_id = ?",
                (wallet_id, member_id),
            )
            tokens = conn.execute(
                "DELETE FROM api_tokens WHERE wallet_id = ? AND member_id = ?",
                (wallet_id, member_id),
            ).rowcount
            shares = conn.execute(
                "DELETE FROM key_shares WHERE wallet_id = ? AND member_id = ?",
                (wallet_id, member_id),
            ).rowcount

    return {
        "ok": True,
        "wallet_id": wallet_id,
        "removed_signer": member_id,
        "remaining_signers": count - 1,
        "tokens_revoked": tokens,
        "key_shares_deleted": shares,
    }
